package cn.kaoyan.assistant;
import java.io.*;import java.nio.file.*;import java.sql.*;import org.json.*;
public class LearningStoreTest{public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("learning-db").toFile();JSONObject state=new JSONObject("{\"schema\":1,\"tasks\":[],\"notes\":[],\"mistakes\":[],\"files\":[]}");String body=String.join("",java.util.Collections.nCopies(3100000,"中"));state.getJSONArray("notes").put(new JSONObject().put("id","long").put("body",body));File old=new File(root,"learning.json");Files.write(old.toPath(),state.toString().getBytes("UTF-8"));LearningStore store=new LearningStore(root);if(!store.load().getJSONArray("notes").getJSONObject(0).getString("body").equals(body))throw new AssertionError("legacy migration above 8MB truncated");if(!old.isFile())throw new AssertionError("migration removed rollback copy");JSONObject pdf=new JSONObject().put("id","p").put("body","aabb").put("pages",new JSONArray().put(new JSONObject().put("page",1).put("body","aa")).put(new JSONObject().put("page",2).put("body","bb")));state.getJSONArray("files").put(pdf);pdf.put("body","aabb拉格朗日中值定理");pdf.getJSONArray("pages").getJSONObject(1).put("body","bb拉格朗日中值定理");store.save(state);if(store.search("未知词").length()!=0)throw new AssertionError("unexpected phrase");if(store.search("bb拉格朗日").length()!=1)throw new AssertionError("text index missing");JSONObject loaded=store.load();if(!loaded.getJSONArray("files").getJSONObject(0).getString("body").equals("aabb拉格朗日中值定理"))throw new AssertionError("page text reconstruction");try(Connection db=DriverManager.getConnection("jdbc:sqlite:"+new File(root,"learning.db"));Statement q=db.createStatement();ResultSet r=q.executeQuery("SELECT count(*) FROM texts WHERE owner='files:p'")){if(r.getInt(1)!=2)throw new AssertionError("PDF body duplicated");}JSONObject invalid=new JSONObject(state.toString());invalid.getJSONArray("notes").put(new JSONObject().put("id","long").put("body","duplicate"));boolean refused=false;try{store.save(invalid);}catch(Exception e){refused=true;}if(!refused||!store.load().getJSONArray("notes").getJSONObject(0).getString("body").equals(body))throw new AssertionError("transaction did not roll back");state.put("pendingFileDeletes",new JSONArray().put("guard.pdf"));state.getJSONArray("files").getJSONObject(0).put("path","guard.pdf");store.save(state);if(store.canDelete("guard.pdf"))throw new AssertionError("referenced original deletable");state.put("files",new JSONArray());store.save(state);if(!store.canDelete("guard.pdf"))throw new AssertionError("durably queued orphan not deletable");state.put("organizationUndo",new JSONObject().put("protectedPaths",new JSONArray().put("guard.pdf")));store.save(state);if(store.canDelete("guard.pdf"))throw new AssertionError("undo original deletable");System.out.println("SQLite migration >8MB, preserved legacy, split text roundtrip, no duplicate PDF body, rollback passed");}}
